#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int c, e; struct Node* n; } Node;
Node* append(Node* h, int c, int e) {
    if(c == 0) return h;
    Node* nn = malloc(sizeof(Node)); nn->c=c; nn->e=e; nn->n=NULL;
    if(!h) return nn;
    Node* t = h; while(t->n) t=t->n; t->n = nn;
    return h;
}
int main() {
    int N, M, c, e; Node *h1=NULL, *h2=NULL, *res=NULL;
    if(scanf("%d", &N) != 1) return 0;
    while(N--) { scanf("%d %d", &c, &e); h1 = append(h1, c, e); }
    scanf("%d", &M);
    while(M--) { scanf("%d %d", &c, &e); h2 = append(h2, c, e); }
    while(h1 && h2) {
        if(h1->e > h2->e) { res = append(res, h1->c, h1->e); h1=h1->n; }
        else if(h1->e < h2->e) { res = append(res, h2->c, h2->e); h2=h2->n; }
        else { int sum = h1->c + h2->c; if(sum!=0) res=append(res, sum, h1->e); h1=h1->n; h2=h2->n; }
    }
    while(h1) { res = append(res, h1->c, h1->e); h1=h1->n; }
    while(h2) { res = append(res, h2->c, h2->e); h2=h2->n; }
    if(!res) { printf("0 0\n"); return 0; }
    Node* t=res;
    while(t) { printf("%d %d%c", t->c, t->e, t->n?' ':'\n'); t=t->n; }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
typedef struct Node { int c, e; struct Node* n; } Node;
Node* ins(Node* h, int c, int e) {
    if(c==0) return h;
    if(!h || h->e < e) { Node* nn=malloc(sizeof(Node)); nn->c=c; nn->e=e; nn->n=h; return nn; }
    if(h->e == e) { h->c+=c; if(h->c==0) { Node* t=h->n; free(h); return t; } return h; }
    Node* t=h; while(t->n && t->n->e > e) t=t->n;
    if(t->n && t->n->e == e) { t->n->c+=c; if(t->n->c==0) { Node* tm=t->n; t->n=tm->n; free(tm); } } else { Node* nn=malloc(sizeof(Node)); nn->c=c; nn->e=e; nn->n=t->n; t->n=nn; }
    return h;
}
int main() {
    int n, m, c, e; Node *h1=NULL, *h2=NULL, *r=NULL;
    if(scanf("%d", &n)!=1) return 0;
    while(n--) { scanf("%d%d", &c, &e); h1=ins(h1, c, e); }
    scanf("%d", &m);
    while(m--) { scanf("%d%d", &c, &e); h2=ins(h2, c, e); }
    for(Node* i=h1; i; i=i->n) for(Node* j=h2; j; j=j->n) r=ins(r, i->c*j->c, i->e+j->e);
    if(!r) { printf("0 0\n"); return 0; }
    for(Node* t=r; t; t=t->n) printf("%d %d%c", t->c, t->e, t->n?' ':'\n');
    return 0;
}
